import { expect, test } from 'bun:test';

import { preserveContributorsSection } from '../src/write/utils/preserveContributorsSection.js';

const start = '<!-- readme: contributors -start -->';
const end = '<!-- readme: contributors -end -->';
const emptyReadme = '# Documentation\n\n' + start + '\n' + end + '\n';
const avatarSection = [
  '<!-- Generated by Paradox contributor avatars -->',
  '',
  '## Contributors',
  '',
  '<a href="https://github.com/octocat"><img src="https://avatars.githubusercontent.com/u/1?v=4&amp;s=72" width="72" height="72" alt="octocat" /></a>',
].join('\n');

test('keeps valid avatars visible across documentation regeneration', () => {
  const existing = emptyReadme.replace(end, avatarSection + '\n' + end);
  expect(preserveContributorsSection(emptyReadme, existing)).toBe(existing);
  expect(preserveContributorsSection(existing, existing)).toBe(existing);
});

test('does not display a heading without contributor avatars', () => {
  expect(preserveContributorsSection(emptyReadme, emptyReadme)).toBe(emptyReadme);
  expect(emptyReadme).not.toContain('## Contributors');
});

test('drops malformed old tables and untrusted contributor blocks', () => {
  const broken = emptyReadme.replace(end, '<table><tbody><tbody></table>\n' + end);
  const fake = emptyReadme.replace(end, '## Contributors\n' + end);
  expect(preserveContributorsSection(emptyReadme, broken)).toBe(emptyReadme);
  expect(preserveContributorsSection(emptyReadme, fake)).toBe(emptyReadme);
});

test('leaves disabled contributor output unchanged', () => {
  const withoutMarkers = '# Documentation\n';
  const existing = emptyReadme.replace(end, avatarSection + '\n' + end);
  expect(preserveContributorsSection(withoutMarkers, existing)).toBe(withoutMarkers);
});
